import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    ema = np.zeros(len(close), dtype=float)
    ema[0] = close[0]
    for t in range(1, len(close)):
        ema[t] = 0.2 * close[t] + 0.8 * ema[t-1]

    pos = np.zeros(len(close), dtype=int)
    for t in range(len(close)):
        if ema[t] < close[t]:
            pos[t] = 1
        else:
            pos[t] = 0
    return pd.Series(pos, index=df.index)
