import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    change = np.diff(close)
    gain = np.maximum(change, 0)
    loss = np.maximum(-change, 0)
    avg_gain = np.zeros(len(close))
    avg_loss = np.zeros(len(close))
    avg_gain[1] = gain[1]
    avg_loss[1] = loss[1]

    for t in range(2, len(close)):
        avg_gain[t] = avg_gain[t-1] + (gain[t] - avg_gain[t-1]) / 16
        avg_loss[t] = avg_loss[t-1] + (loss[t] - avg_loss[t-1]) / 16

    rsi = 100 - 100 / (1 + avg_gain / avg_loss)
    rsi = np.where(avg_loss == 0, 100, rsi)

    pos = np.zeros(len(close), dtype=int)
    state = 0
    for t in range(len(close)):
        if state == 0:
            if rsi[t] < 28:
                state, entry = 1, close[t]
            elif rsi[t] > 72:
                state, entry = -1, close[t]
        elif state == 1:
            if rsi[t] > 52:
                state = 0
        elif state == -1:
            if rsi[t] < 52:
                state = 0
        pos[t] = state
    return pd.Series(pos, index=df.index)
