import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    m = close.rolling(60).mean().to_numpy()
    s = close.rolling(60).std().to_numpy()
    pos = np.zeros(len(close), dtype=int)
    state = 0
    for t in range(len(close)):
        if np.isnan(m[t]) or np.isnan(s[t]):
            state = 0
        elif state == 0:
            if close[t] < m[t] - 2 * s[t]:
                state, pos[t] = 1, 1
            elif close[t] > m[t] + 2 * s[t]:
                state, pos[t] = -1, -1
        elif state == 1:
            if close[t] >= m[t] - 0.25 * s[t]:
                state, pos[t] = 0, 0
        elif state == -1:
            if close[t]<= m[t] + 0.25 * s[t]:
                state, pos[t] = 0, 0
    return pd.Series(pos, index=df.index)
