import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    vol = df["volume"]
    one_bar_returns = (close / close.shift(1)) - 1
    one_bar_returns = one_bar_returns[1:]  # Shift to align with vol
    vol_12 = one_bar_returns.rolling(12).std()
    sma_15 = close.rolling(15).mean()

    pos = np.zeros(len(close), dtype=int)
    state = 0
    for t in range(len(close)):
        if state == 0:
            if close[t] > sma_15[t]:
                state = 1
            elif vol_12[t] < 0.02:
                state = 1
